'use strict';

// MODULES //

var appendFile = require( 'node:fs/promises' ).appendFile;
var boundedMessage = require( '@data-apis/errors/bounded-message' );


// FUNCTIONS //

/**
* Escapes a value for a Markdown table cell.
*
* @private
* @param {*} value - value
* @returns {string} escaped value
*/
function escapeTable( value ) {
	return boundedMessage( value, 240 ).replaceAll( '|', '\\|' ).replaceAll( '\n', ' ' );
}


// MAIN //

/**
* Appends a sanitized harvest summary to a GitHub Actions summary file.
*
* @param {Object} summary - machine summary
* @param {string} [target] - summary path
* @returns {Promise<void>} promise
*/
async function writeActionsSummary( summary, target ) {
	var lines;

	target = target || process.env.GITHUB_STEP_SUMMARY;
	if ( !target ) {
		return;
	}
	lines = [
		'# Array API compliance harvest',
		'',
		'| Library/source | Status | Stored | Notes |',
		'| --- | --- | ---: | --- |'
	];
	summary.sources.forEach( function addSource( source ) {
		lines.push( '| ' + escapeTable( source.library_id + '/' + source.source_id ) + ' | ' + escapeTable( source.status ) + ' | ' + source.dispositions.filter( function stored( item ) {
			return item.status === 'stored';
		} ).length + ' | ' + escapeTable( source.errors.join( '; ' ) ) + ' |' );
	} );
	if ( summary.warnings.length > 0 ) {
		lines.push( '', '## Warnings', '' );
		summary.warnings.forEach( function addWarning( warning ) {
			lines.push( '- ' + escapeTable( warning ) );
		} );
	}
	await appendFile( target, lines.join( '\n' ) + '\n', 'utf8' );
}


// EXPORTS //

module.exports = writeActionsSummary;
